import { useCallback, useEffect, useRef } from 'react'
import navigate from '../assets/sounds/navigate.wav'
import toggle from '../assets/sounds/toggle.wav'
import back from '../assets/sounds/back.wav'
import launch from '../assets/sounds/launch.wav'
import { createSoundPool } from './soundPool'

/** Original PCM assets generated by scripts/generate-sounds.js; no live oscillators. */
const SOURCES = { navigate, toggle, back, launch }
export const emitSound = (name) =>
  window.dispatchEvent(new CustomEvent('zenith-sound', { detail: name }))

/** One preloaded pool for the app. Six overlapping navigation voices have no input-rate throttle. */
export default function useSoundEffects(enabled = true) {
  const players = useRef(null)
  useEffect(() => {
    const pool = createSoundPool(SOURCES)
    players.current = pool
    return () => {
      pool.dispose()
      players.current = null
    }
  }, [])
  useEffect(() => {
    players.current?.setEnabled(enabled)
  }, [enabled])
  const play = useCallback((name) => {
    players.current?.play(name)
  }, [])
  useEffect(() => {
    const receive = ({ detail }) => play(detail)
    window.addEventListener('zenith-sound', receive)
    return () => window.removeEventListener('zenith-sound', receive)
  }, [play])
  return { play }
}
